class TTLCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        self.cache = {}
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.ttl_data = {}
        if typed:
            self.cache = {}
            self.typed = True

    def __getitem__(self, key):
        if self.typed:
            if key not in self.cache:
                raise KeyError(f"{key} not in cache")
            if self.cache[key][1] < self.timer():
                del self.cache[key]
                raise KeyError(f"{key} expired")
            return self.cache[key][0]
        else:
            if key not in self.cache:
                raise KeyError(f"{key} not in cache")
            if self.cache[key] < self.timer():
                del self.cache[key]
                raise KeyError(f"{key} expired")
            return self.cache[key]

    def __setitem__(self, key, value):
        if self.typed:
            if key in self.cache:
                raise KeyError(f"{key} already in cache")
            if self.cache and len(self.cache) == self.maxsize:
                self.evict()
            self.cache[key] = (value, self.timer() + self.ttl)
        else:
            if key in self.cache:
                raise KeyError(f"{key} already in cache")
            if self.cache and len(self.cache) == self.maxsize:
                self.evict()
            self.cache[key] = value

    def __delitem__(self, key):
        if self.typed:
            if key not in self.cache:
                raise KeyError(f"{key} not in cache")
            del self.cache[key]
        else:
            if key not in self.cache:
                raise KeyError(f"{key} not in cache")
            del self.cache[key]

    def evict(self):
        if self.typed:
            oldest_key = min(self.cache, key=self.cache.get)
            del self.cache[oldest_key]
            del self.ttl_data[oldest_key]
        else:
            oldest_key = min(self.cache)
            del self.cache[oldest_key]

