    try:
        if e is None:
            return "None"
        if isinstance(e, Exception):
            path = traceback.extract_stack(limit=max_level)
            message = ""
            for frame in path:
                filename = frame.filename
                function = frame.funcname
                line_number = frame.lineno
                if cls._should_include_path(filepath, function, line_number, max_path_level):
                    message += f"{filename}:{line_number} - {function}: {e}\n"
