        formatted_exception = e.__class__.__name__ + ": " + str(e)
        formatted_exception += "\n" + _extract_stack_trace(e, max_level)

        if max_path_level > 0:
            current_frame = sys._getframe().f_back
            while True:
                current_frame = current_frame.f_back
                if current_frame is None or current_frame.f_code.co_name == '_main_':
                    break
                if current_frame.f_code.co_name in ("<module>"):
                    break
            formatted_exception += "\nPath:\n"
            while current_frame is not None and current_frame.f_code.co_name != "<module>":
                formatted_exception += f"{'  ' * (max_path_level - current_frame.f_lineno + 1)}{'-> ' if current_frame != sys._getframe().f_back else '>'}" + current_frame.f_code.co_name + "\n"
                current_frame = current_frame.f_back

