    def extostr(cls, e, max_level=30, max_path_level=5):
        if not isinstance(e, Exception):
            raise ValueError("e must be an instance of Exception")

        stack_trace = []
        # Capture only the relevant stack frames
        for frame in traceback.extract_stack(limit=max_level + 1):
            stack_trace.append(f"{frame.filename}:{frame.lineno} - {frame.name}")

        # Format the call stack
        call_stack = ''
        for frame in stack_trace[::-1]:
            if call_stack and frame in call_stack:
                continue  # Avoid redundant frames when going back
            call_stack += frame + '\n'

        exception_details = {}
        try:
            # Get detailed traceback
            complete_traceback = traceback.format_exc()
            # Extract details about the exception
            if 'TypeError' in complete_traceback:
                exception_details = {'type': 'TypeError'}
            elif 'AttributeError' in complete_traceback:
                exception_details = {'type': 'AttributeError'}
            # Extract other exceptions
            else:
                parts = complete_traceback.split(':')
                if len(parts) < 3:
                    continue
                exception_details = {'name': parts[0], 'message': parts[2] if len(parts) > 2 else ''}

        except Exception as exc:
            # Handle any errors during traceback extraction
            stack_trace.append(f"Exception occurred while trying to gather details: {exc}")

        # Format the exception details
       .details = ''
        for key, value in exception_details.items():
            if value == '':
                continue
            details += f"{key}: {value}\n"

        # Construct the formatted exception string
        formatted_exception = f'{e.__class__.__name__}: {e.message}\n{details}\nCall stack:\n{call_stack}\n'
        return formatted_exception

