def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    if not isinstance(file_name, str):
        raise ValueError("file_name must be a string")
    if not isinstance(text_buffer, str):
        raise ValueError("text_buffer must be a string")
    if not isinstance(encoding, str):
        raise ValueError("encoding must be a string")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    full_path = os.path.join(os.getcwd(), file_name)
    if not os.path.exists(full_path) and not overwrite:
        raise FileNotFoundError(f"File {file_name} does not exist and overwrite is false")
    if os.path.exists(full_path) and overwrite:
        os.remove(full_path)

    with open(full_path, 'wb' if overwrite else 'ab') as f:
        f.write(text_buffer.encode(encoding))

    return f.tell()

