def _legacy_mergeOrderings(orderings):
    seen = {}
    merge_ordering = []

    # Add all orderings to the seen dictionary
    for item in sum(orderings, []):
        seen[item] = seen.get(item, 0) + 1

    # Add non-repeating items at the beginning of the merge order
    for item in [x for item in sum(orderings, []) if not seen[item]]:
        merge_ordering.append(item)

    # Add the remaining items sorted by their occurrence in the orderings
    for item in sorted(set([x for x in seen if seen[x] > 1])):
        merge_ordering.extend([item] * seen[item])

    return merge_ordering

from typing import List

def _legacy_mergeOrderings(orderings: List[List[str]]) -> List[str]:
    order = {obj: i for i, obj in enumerate(orderings)}
    merged = []

    for obj in set().union(*orderings):
        start = min(order[k] for k in next((k for k, o in order.items() if o == obj), None), default=0)
        end = max(order[k] + len(o) for k, o in order.items() if o == obj, default=None)
        merged.extend(o[start:end])

    return merged


