def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, (list, tuple, dict)):
        raise ValueError("Sequence must be a list, tuple, or dictionary")

    def normalize(item):
        if isinstance(item, Declaration):
            return item
        elif isinstance(item, tuple):
            return tuple(normalize(i) for i in item)
        elif isinstance(item, str) and item.endswith("制品"):
            return item.replace("制品", "工程")
        else:
            return item

    normalized_sequence = []
    for item in sequence:
        if isinstance(item, dict) and all(key in item for key in ('declaration', 'content')):
            declaration = item['declaration']
            content = item['content']
            if not isinstance(declaration, Declaration):
                raise ValueError("Declaration should be an instance of Declaration")
            for spec in content:
                normalized_content = [normalize(spec) for spec in spec]
                normalized_sequence.append({'declaration': declaration, 'content': normalized_content})
        else:
            normalized_sequence.append(normalize(item))

    if output:
        normalizing_function = getattr(output, 'normalize', None)
        if normalizing_function:
            normalized_sequence = normalizing_function(normalized_sequence)
    return normalized_sequence

def _normalizeargs(sequence, output=None):
    if not isinstance(sequence, (tuple, list)):
        raise ValueError("Input must be a sequence of interfaces or tuples.")

    normalized_sequences = []
    for element in sequence:
        if isinstance(element, InterfaceDeclaration) and output is None:
            raise ValueError("Output must be specified for non-implements interface declarations.")
        elif isinstance(element, InterfaceDeclaration) and issubclass(output, element):
            normalized_sequences.append(output)
        elif isinstance(element, TupleImpl) and issubclass(output, element.element_type):
