def integral(bins, edges):
    # Check if bins and edges are valid types and have the appropriate length
    if not isinstance(bins, list) or not isinstance(edges, list):
        raise ValueError("bins and edges must be lists")
    if len(bins) < 2 or len(edges) < 3:
        raise ValueError("bins and edges must have at least 3 elements")

    # Compute the integral using the trapezoidal rule
    integral_result = 0.0
    for i in range(len(bins) - 1):
        width = edges[i + 1] - edges[i]
        height = (bins[i + 1] + bins[i]) / 2
        integral_result += width * height

    return integral_result

