        for key, val1 in d1.items():
            val2 = d2.pop(key, None)
            if level > 0:
                if isinstance(val1, Sequence) and isinstance(val2, Sequence):
                    if all(difference(seq1, seq2, level-1) for seq1, seq2 in zip(val1, val2)):
                        continue
                elif isinstance(val1, dict) and isinstance(val2, dict):
                    if difference(val1, val2, level-1) == {}:
