def pretty(self, indent=0, debug=False):
    if not isinstance(self, self.__class__):
        raise ValueError("self must be an instance of this class")
    output = ""
    for key, value in self.__dict__.items():
        if key.startswith("__"):
            continue
        if isinstance(value, dict):
            output += "    " * indent + "{}:\n".format(key)
            output += pretty(value, indent + 1, debug)
        else:
            output += "    " * indent + "{}: {}\n".format(key, value)
    return output

