    if not args:
        return []

    def apply_absorption(expr, other):
        if first_term := expr.get_first_term():
            if first_term == other.get_second_term():
                return other.get_first_term(), None
        if second_term := expr.get_second_term():
            if second_term == other.get_first_term():
                return other.get_second_term(), None
        return expr, other

    if not args or len(args) == 1:
        return args

    result = args[0]

    for expr in args[1:]:
        result, next_expr = apply_absorption(result, expr)
        if next_expr:
            result = result + [next_expr]

    return result

