def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise ValueError("Input must be a timezone-aware datetime object.")

    tz = dt.tzinfo
    if not tz or not callable(tz.utcoffset):
        raise ValueError("Timestamp is ambiguous or not timezone-aware.")

    new_tz = self._new_tz(tz)
    if new_tz is None:
        if dt.utcoffset() < 0:
            raise ValueError("The datetime is in a fold and cannot be converted.")
        return datetime.datetime.combine(dt.date(), dt.time())

    orig_off = dt.utcoffset()
    delta = new_tz.utcoffset(dt) - orig_off

    # Convert dt to the new timezone
    dt = dt.astimezone(new_tz).replace(tzinfo=None)

    # Adjust dt to eliminate the fold while keeping the original offset
    while dt < new_tz.localize(datetime.datetime.utcfromtimestamp(dt.timestamp() + delta)):
        dt -= delta

    return dt

