def next_version(version):
    if not isinstance(version, str):
        raise ValueError("Invalid input. Please provide a string.")
    if not version.isalnum():
        raise ValueError("Invalid input. Please provide a string containing only alphanumeric characters.")

    # Split the version string into components
    parts = version.split('.')

    # Handle zero-prefixed versions
    if parts[-1].startswith('0'):
        parts[-1] = '1'
        for i in range(len(parts) - 2, -1, -1):
            if parts[i] != '0':
                break
            parts[i] = '1'

    # Handle non-zero-prefixed versions without last part being '0'
    if parts[-1] != '0' and len(parts) > 1:
        parts[-1] = str(int(parts[-1]) + 1)

    # Join the parts back into a version string
    next_version_str = '.'.join(parts)

    return next_version_str

def next_version(version):
        if not isinstance(version, str):
            raise ValueError("Invalid input. Expected a string.")

        if not version:
            raise ValueError("Invalid input. Version is empty.")

        if not version.startswith("v") or version.startswith("V"):
            raise ValueError("Invalid input. Version must start with 'v' or 'V'.")

        if len(version) > 2 and not version[1].isdigit():
            return "v0.1"

        if len(version) > 3 and not version[2].digit():
            return "v0.0.1"

        return f"v{version[:2]}.{version[2:4]}"

