        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description
    """
    try:
        # Assuming "0=*" is a herded document indicator
        if os.path.exists(path):
            _, name = os.path.split(path)
            if name == "0=*" and os.path.isfile(path):
                return 'file'
            elif name in {'.', '..'}:
                return 'root'
            else:
                return 'object'
        else:
            return 'other'
    except Exception as e:
