from ruamel.yaml import YAML

def deep_merge_nodes(nodes):
    deep_yaml = YAML()
    deep_yaml.preserve_quotes = True

    def merge_nodes(value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            result = MappingNode(tag=value1.tag, value=[])
            for key, value in value1.value:
                mapped_value = intermediate_lookup(result, key)
                if mapped_value is None:
                    intermediate_lookup(result, key) = merge_nodes(value, value2)
                else:
                    intermediate_lookup(result, key) = merge_nodes(mapped_value, value)
            return result
        elif isinstance(value1, SequenceNode) and isinstance(value2, SequenceNode):
            result = SequenceNode(tag=value1.tag)
            for item in value1.value:
                intermediate_lookup(result, item) = merge_nodes(item, value2)
            return result
        elif value1 == value2:
            return value1
        else:
            return value2

    intermediate_lookup = {}

    for node_type, value in nodes:
        intermediate_node = intermediate_lookup.get(node_type, None)
        if intermediate_node is None:
            intermediate_node = deep_yaml.load(str(value))
            intermediate_lookup[node_type] = intermediate_node
        intermediate_node = intermediate_lookup[node_type]
        intermediate_node.value.extend(value)

    return [deep_yaml.dump(node) for node_type, node in intermediate_lookup.items()]

