    size = size.upper()
    scale = {
        "B": 1,
        "KB": 1024,
        "MB": 1024 * 1024,
        "GB": 1024 * 1024 * 1024,
    }
    if not size.endswith(('B', 'KB', 'MB', 'GB')):
