def _replace_url_args(url, url_args):
    parsed_url = urllib.parse.urlparse(url)

    # Ensure the URL has query parameters
    if parsed_url.query is None:
        return url

    # Extract and replace the URL arguments
    query_pairs = urllib.parse.parse_qs(parsed_url.query)
    replace_dict = {query_part: value[0] for query_part, value in query_pairs.items() if query_part in url_args}

    # Update the query parameters
    updated_query = urllib.parse.urlencode(replace_dict, doseq=True)
    new_parsed_url = parsed_url._replace(query=updated_query)

    return new_parsed_url.geturl()

