def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet or number < 0:
        raise ValueError("Invalid input: alphabet must not be empty and number must be non-negative")

    if padding is None:
        padding = 0

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding > 0:
        digits += ['0'] * padding

    return ''.join(digits[::-1])

