def subclasses(cls):
    seen = set()
    stack = [cls]
    while stack:
        cls = stack.pop()
        for sub in cls.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet:
        raise ValueError("Input string and alphabet cannot be empty")
    num = 0
    base = len(alphabet)
    for char in string:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' is not in the alphabet")
        num = (num * base) + alphabet.index(char)
    return num

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet or not all(ord(c) < ord('a') for c in alphabet):
        raise ValueError("Invalid input: string, alphabet must not be None and alphabet must be a list of lowercase letters.")

    number = 0
    for i, char in enumerate(reversed(string)):
        if char not in alphabet:
            raise ValueError("Invalid character:", char)
        number += (ord(char) - ord('a')) * (26 ** i)

    return number

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet:
        raise ValueError("Input strings or alphabet must not be empty")

    return int(string, alphabet.index(max(alphabet)))

from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    number = 0
    power = len(alphabet) - 1

    for char in string:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' is not in the alphabet.")
        number += alphabet.index(char) * (len(alphabet) ** power)
        power -= 1

    return number

