import re

def make_find_paths(find_paths):
    """Transform list of find path fragments into glob patterns as appropriate."""
    result = []
    for fragment in find_paths:
        if re.match(r'^pp:\w+(\/.*)$', fragment):
            # If the fragment is already a pattern, pass through it
            result.append(fragment)
        else:
            # Expand the fragment into a glob pattern
            try:
                parts = fragment.split(':')
                base, pattern = parts[1].strip(), parts[0]
                result.extend(['sh:**/*' + base + '/' + pattern + ''])  # assuming sh: protocol for shell globs
            except IndexError:
                # Handle the case where the fragment does not match the expected format
                raise ValueError(f"Invalid find path fragment: {fragment}")
    return result

