import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    process_args = []
    if commands:
        process_args.append(commands)

    if args:
        process_args.extend(args)

    result = None
    try:
        if verbose:
            print(f"Executing: {' '.join(process_args)}")

        process = subprocess.Popen(process_args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL, text=True)

        stdout, stderr = process.communicate()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, f"Command failed with return code {process.returncode}")

        output = stdout
        if stderr:
            output += stderr

        result = {"stdout": output, "returncode": process.returncode}

        if verbose:
            print(f"Command output: {stdout}")

    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {' '.join(process_args)}")
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, f"Command failed with return code {e.returncode}")
    except subprocess.TimeoutExpired:
        process.kill()
        raise subprocess.TimeoutExpired("Command took too long to execute")
    finally:
        if process.args:
            next_command = process.args[0]
            run_command(next_command, args[1:], cwd=cwd, verbose=verbose, hide_stderr=hide_stderr, env=env)

