from typing import Tuple, Set, Callable

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    current_tag = None
    in_code_block = False

    for char in text:
        if char == '[':
            if in_code_block:
                # Ignore tags within code blocks
                in_code_block = False
            else:
                current_tag = char
        elif char == ']':
            if in_code_block:
                in_code_block = False
            elif current_tag:
                tags.add(current_tag)
                if callable(replacer):
                    tag_text = current_tag
                    current_tag = replacer(tag_text)
                else:
                    current_tag = ""
            else:
                pass
        elif char == '\n':
            in_code_block = False  # New line starts a new code block
        elif not in_code_block:
            tags.add(char)  # Non-code block characters are considered tags

    return tags, ''.join(tags)

