def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    current_tag = None
    in_code_block = False

    for char in text:
        if char == "'" and not in_code_block:
            if current_tag:
                tags.add(current_tag)
                current_tag = None
        elif char == "`":
            in_code_block = not in_code_block
        elif char == '#' and not in_code_block and not current_tag:
            current_tag = char
        elif current_tag:
            current_tag += char

    if current_tag:
        tags.add(current_tag)

    if replacer:
        replaced_text = replacer(text)
    else:
        replaced_text = text

    return tags, replaced_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise ValueError("Text must be a string")

    lines = text.split('\n')
    processed_lines = []

    for line in lines:
        if "|" in line:
            parts = line.split("|")
            link_text = parts[0]
            link_url = parts[1] if len(parts) > 1 else ""
            processed_line = f'<a href="{link_url}"><strong>{link_text}</strong></a>'
            processed_lines.append(processed_line)
        else:
            processed_lines.append(line)

    return '\n'.join(processed_lines)

