def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Validate the input
    if not isinstance(document, str):
        raise TypeError("Input must be a string")

    # Attempt to parse the document as JSON
    try:
        data = json.loads(document)
        return data  # Return the parsed data
    except json.JSONDecodeError:
        # If parsing as JSON fails, try parsing as XRD
        try:
            import rdflib as rdf
        except ImportError:
            raise ImportError("rdflib library is required to parse XRD")

        graph = rdf.Graph()
        try:
            graph.parse(data=bytes(document, 'utf-8'), format='application/xrd+json')
            data = {uri: dict(graph.serialize(uri=uri)) for uri in graph.subjects()}
            return data  # Return the parsed data
        except rdf.ParserException:
            # If parsing as XRD also fails, return an error message
            raise ValueError("Failed to parse the document as JSON or XRD")

