def retrieve_and_parse_diaspora_webfinger(handle):
    # Validate input handle
    if not isinstance(handle, str):
        raise ValueError("Handle must be a string.")
    if len(handle) < 3 or len(handle) > 50:
        raise ValueError(f"Handle must be between 3 and 50 characters (inclusive).")

    # Construct the Diaspora webfinger URL
    webfinger_url = f"https://diaspora.org/server/api/webfinger?resource={handle}&rels={webfinger_url_avatar}"

    # Send a GET request to fetch the webfinger document
    try:
        response = requests.get(webfinger_url)
        response.raise_for_status()  # Raise an exception for HTTP errors (e.g., 404 or 500)
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve the webfinger document: {e}")

    # Parse the HTML response
    try:
        soup = BeautifulSoup(response.text, 'html.parser')
    except Exception as e:
        raise Exception(f"Failed to parse the webfinger document: {e}")

    # Extract relevant metadata from the webfinger document
    try:
        subject = soup.find('meta', {'property': 'self'})
        if subject:
            subject = subject['content']
        else:
            raise ValueError("Could not find 'self' meta tag.")
        links = soup.find_all('link', rel='alternate')
        for link in links:
            href = link.get('href')
            media_type = link.get('type')
            if href.endswith('image') and media_type == 'image/jpeg':
                image_url = href
                break
        else:
            raise ValueError("Could not find an image link with the correct media type.")
        email = soup.find('meta', {'property': 'email'})
        if email:
            email = email['content']
        else:
            raise ValueError("Could not find 'email' meta tag.")
        name = soup.find('meta', {'property': 'name'})
        if name:
            name = name['content']
        else:
            raise ValueError("Could not find 'name' meta tag.")
    except Exception as e:
        raise Exception(f"Failed to parse the webfinger document: {e}")

    # Prepare the parsed data as a dictionary
    data = {
        'subject': subject,
        'image_url': image_url,
        'email': email,
        'name': name
    }

    return data

