def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flattened_dict = {}
    try:
        # Define the paths to the properties file
        properties_path = os.path.join(plugin_dir, 'properties.json')
        if not os.path.exists(properties_path):
            raise FileNotFoundError(f"Properties file not found at {properties_path}")

        # Load the properties from the file
        with open(properties_path, 'r') as file:
            properties = json.load(file)

        # Flatten the dictionary
        for key, value in properties.items():
            if isinstance(value, dict):
                for sub_key, sub_value in value.items():
                    flattened_dict[f"{key}.{sub_key}"] = sub_value
            else:
                flattened_dict[key] = value

        return flattened_dict
    except FileNotFoundError as e:
        print(f"Unable to find properties file: {e}")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

import os
import yaml

def get_plugin_spec_flatten_dict(plugin_dir):
    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"The plugin directory {plugin_dir} does not exist.")

    flatten_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith(".yml"):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    spec = yaml.safe_load(f)
                    for key, value in spec.items():
                        flatten_dict[key.replace('.', '_')] = value

    return flatten_dict

